const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(data[0]);
const freq = new Uint32Array(100001);

let left = 0;
let maxLen = 0;

for (let right = 0; right < n; right++) {
  const value = Number(data[right + 1]);
  freq[value]++;

  while (freq[value] > 1) {
    const leftValue = Number(data[left + 1]);
    freq[leftValue]--;
    left++;
  }

  const len = right - left + 1;
  if (len > maxLen) maxLen = len;
}

console.log(maxLen);
